import React, { useState, useMemo } from 'react';
import { Search, ArrowUpDown, Plus, Layers, Filter } from 'lucide-react';
import { Asset, AssetType } from '../types/portfolio';
import { AssetCard } from './AssetCard';

interface AssetListProps {
  assets: Asset[];
  selectedType: AssetType | 'ALL';
  onEditAsset: (asset: Asset) => void;
  onDeleteAsset: (id: number) => void;
  onOpenAddModal: () => void;
}

export const AssetList: React.FC<AssetListProps> = ({
  assets,
  selectedType,
  onEditAsset,
  onDeleteAsset,
  onOpenAddModal,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<'value' | 'gain' | 'date' | 'name'>('value');
  const [sortAsc, setSortAsc] = useState(false);

  // Filter and sort assets
  const filteredAssets = useMemo(() => {
    return assets
      .filter((asset) => {
        // Category filter
        if (selectedType !== 'ALL' && asset.assetType !== selectedType) {
          return false;
        }
        // Search filter
        if (searchQuery.trim()) {
          const q = searchQuery.toLowerCase();
          const matchesName = asset.name.toLowerCase().includes(q);
          const matchesNotes = asset.notes?.toLowerCase().includes(q) || false;
          const matchesTicker = asset.ticker?.toLowerCase().includes(q) || false;
          const matchesLocation = asset.location?.toLowerCase().includes(q) || false;
          const matchesBank = asset.bankName?.toLowerCase().includes(q) || false;
          return matchesName || matchesNotes || matchesTicker || matchesLocation || matchesBank;
        }
        return true;
      })
      .sort((a, b) => {
        let diff = 0;
        if (sortBy === 'value') {
          diff = (b.metrics?.currentValue || 0) - (a.metrics?.currentValue || 0);
        } else if (sortBy === 'gain') {
          diff = (b.metrics?.profitLoss || 0) - (a.metrics?.profitLoss || 0);
        } else if (sortBy === 'date') {
          diff = new Date(b.purchaseDate).getTime() - new Date(a.purchaseDate).getTime();
        } else if (sortBy === 'name') {
          diff = a.name.localeCompare(b.name);
        }
        return sortAsc ? -diff : diff;
      });
  }, [assets, selectedType, searchQuery, sortBy, sortAsc]);

  return (
    <div className="space-y-4">
      
      {/* Search & Sort Controls Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-slate-900/60 p-3 rounded-2xl border border-slate-800">
        
        {/* Search input */}
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search gold bars, shares, property, FD, or notes..."
            className="w-full bg-slate-800/80 border border-slate-700/80 rounded-xl pl-9 pr-4 py-2 text-xs sm:text-sm text-white placeholder-slate-400 focus:outline-none focus:border-amber-500 transition-colors"
          />
        </div>

        {/* Sort Select */}
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 text-xs text-slate-400 font-medium pl-1">
            <Filter className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">Sort:</span>
          </div>

          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
            className="bg-slate-800/80 border border-slate-700/80 rounded-xl px-3 py-2 text-xs sm:text-sm text-slate-200 focus:outline-none focus:border-amber-500 cursor-pointer"
          >
            <option value="value">Highest Valuation</option>
            <option value="gain">Highest Profit (₹)</option>
            <option value="date">Recent Purchase</option>
            <option value="name">Asset Name (A-Z)</option>
          </select>

          <button
            onClick={() => setSortAsc(!sortAsc)}
            className="p-2 bg-slate-800/80 hover:bg-slate-700/80 border border-slate-700/80 rounded-xl text-slate-300 hover:text-white transition-all"
            title={sortAsc ? 'Ascending Order' : 'Descending Order'}
          >
            <ArrowUpDown className="w-4 h-4" />
          </button>
        </div>

      </div>

      {/* Assets Grid */}
      {filteredAssets.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredAssets.map((asset) => (
            <AssetCard
              key={asset.id || Math.random()}
              asset={asset}
              onEdit={onEditAsset}
              onDelete={onDeleteAsset}
            />
          ))}
        </div>
      ) : (
        /* Empty State */
        <div className="text-center py-16 px-4 bg-slate-900/40 border border-slate-800/80 rounded-3xl">
          <div className="w-16 h-16 rounded-2xl bg-amber-500/10 border border-amber-500/20 text-amber-400 flex items-center justify-center mx-auto mb-4">
            <Layers className="w-8 h-8" />
          </div>
          <h3 className="text-lg font-bold text-slate-200 mb-1">No Assets Found</h3>
          <p className="text-xs sm:text-sm text-slate-400 max-w-md mx-auto mb-6">
            {searchQuery 
              ? `No holdings matching "${searchQuery}". Try clearing your search query.`
              : `You haven't added any assets under this category yet.`}
          </p>
          <button
            onClick={onOpenAddModal}
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-gradient-to-r from-amber-400 to-yellow-500 hover:from-amber-300 hover:to-yellow-400 text-slate-950 font-bold text-xs sm:text-sm shadow-lg shadow-amber-500/20 active:scale-95 transition-all"
          >
            <Plus className="w-4 h-4 stroke-[3]" />
            <span>Add New Asset</span>
          </button>
        </div>
      )}

    </div>
  );
};
